from pathlib import Path
import os
import stat

TARGET = Path("scanner_core_region_ocr.py")
BACKUP = Path("scanner_core_region_ocr_before_tg_focus_v21_patch.py")

if not TARGET.exists():
    raise SystemExit("ERROR: scanner_core_region_ocr.py not found. Run this from the PutnamCollectibles project folder.")

s = TARGET.read_text(encoding="utf-8")

if "TG_OCR_FOCUS_V2_1_PATCH" in s:
    print("TG OCR Focus v2.1 patch already appears to be installed. No changes made.")
    raise SystemExit(0)

try:
    os.chmod(TARGET, stat.S_IWRITE | stat.S_IREAD)
except Exception:
    pass

BACKUP.write_text(s, encoding="utf-8")

append = '\n# --- TG_OCR_FOCUS_V2_1_PATCH ---\n# Purpose:\n# 1) Improve name selection by comparing all name OCR attempts against database names.\n# 2) Add TG-number-only OCR from existing number_crop and bottom_id_crop.\n#\n# This does not change locked geometry, crop coordinates, Studio HTML, scanner_server, or DB files.\n\n_previous_scan_image_before_tg_focus_v21 = scan_image\n\ndef _tg_v21_norm_name(s):\n    import re\n    s = str(s or "").lower().replace("Ã©", "e")\n    s = re.sub(r"[^a-z0-9\' ]", " ", s)\n    return re.sub(r"\\s+", " ", s).strip()\n\ndef _tg_v21_clean_display_name(s):\n    import re\n    raw = str(s or "")\n    raw = raw.replace("™", "").replace("®", "")\n    raw = re.sub(r"[^A-Za-z0-9\' .:-]", " ", raw)\n    raw = re.sub(r"\\s+", " ", raw).strip()\n    return raw\n\ndef _tg_v21_load_rows(sqlite_path):\n    # Prefer existing cached DB helper if present.\n    if "_db_assist_load_rows_v1" in globals():\n        return _db_assist_load_rows_v1(sqlite_path)\n\n    import sqlite3\n    from pathlib import Path\n    p = Path(sqlite_path)\n    if not p.exists():\n        return []\n    con = sqlite3.connect(str(p))\n    con.row_factory = sqlite3.Row\n    rows = [dict(r) for r in con.execute("select * from pokemon_cards").fetchall()]\n    con.close()\n    return rows\n\ndef _tg_v21_best_name_from_attempts(result, rows):\n    from difflib import SequenceMatcher\n\n    attempts = ((result.get("ocr_attempts") or {}).get("name") or [])\n    raw_texts = []\n\n    current = ((result.get("ocr") or {}).get("name") or "")\n    if current:\n        raw_texts.append(current)\n\n    for a in attempts:\n        t = a.get("text", "")\n        if t:\n            raw_texts.append(t)\n\n    cleaned_texts = []\n    for t in raw_texts:\n        c = _tg_v21_clean_display_name(t)\n        if c and len(c) >= 3:\n            cleaned_texts.append(c)\n\n    # Deduplicate, keep order.\n    seen = set()\n    uniq_texts = []\n    for c in cleaned_texts:\n        k = c.lower()\n        if k not in seen:\n            seen.add(k)\n            uniq_texts.append(c)\n\n    if not uniq_texts:\n        return "", 0.0, ""\n\n    # Compare against unique DB names.\n    db_names = sorted({str(r.get("card_name", "") or "") for r in rows if r.get("card_name")})\n    best_db = ""\n    best_score = 0.0\n    best_ocr = ""\n\n    for ocr_text in uniq_texts:\n        ocr_n = _tg_v21_norm_name(ocr_text)\n        if not ocr_n:\n            continue\n        for db_name in db_names:\n            sim = SequenceMatcher(None, ocr_n, _tg_v21_norm_name(db_name)).ratio()\n            if sim > best_score:\n                best_score = sim\n                best_db = db_name\n                best_ocr = ocr_text\n\n    return best_db, best_score, best_ocr\n\ndef _tg_v21_repair_number(text):\n    import re\n\n    raw = str(text or "").upper()\n    raw = raw.replace("\\\\", "/").replace("|", "/").replace(",", "/")\n    raw = raw.replace(" ", "").replace("\\n", "")\n    raw = raw.replace("’", "").replace("\'", "").replace("`", "").replace(".", "")\n\n    # Let existing repair try first if present.\n    if "_tg_focus_v2_repair" in globals():\n        prev = _tg_focus_v2_repair(raw)\n        if prev and prev.startswith("TG"):\n            return prev\n    if "_bottom_id_clean_special_number" in globals():\n        prev = _bottom_id_clean_special_number(raw)\n        if prev and prev.startswith("TG"):\n            return prev\n\n    t = raw.replace("O", "0").replace("I", "1").replace("L", "1").replace("S", "5")\n\n    # Direct forms.\n    m = re.search(r"TG0*(\\d{1,2})/?TG0*(\\d{1,2})", t)\n    if m:\n        left = int(m.group(1))\n        right = int(m.group(2))\n        if 1 <= left <= 30 and 1 <= right <= 99:\n            return f"TG{left:02d}/TG{right}"\n\n    m = re.search(r"TG0*(\\d{1,2})/0*(\\d{1,2})", t)\n    if m:\n        left = int(m.group(1))\n        right = int(m.group(2))\n        if 1 <= left <= 30 and 1 <= right <= 99:\n            return f"TG{left:02d}/TG{right}"\n\n    # If OCR sees just 02/30, infer TG.\n    m = re.search(r"0*(\\d{1,2})/0*(30)", t)\n    if m:\n        left = int(m.group(1))\n        if 1 <= left <= 30:\n            return f"TG{left:02d}/TG30"\n\n    # Specific "TG02TG30", "TGO2TG30", etc.\n    m = re.search(r"TG0*(\\d{1,2})\\D*TG?0*(30)", t)\n    if m:\n        left = int(m.group(1))\n        if 1 <= left <= 30:\n            return f"TG{left:02d}/TG30"\n\n    return ""\n\ndef _tg_v21_ocr_number_from_crop(crop_path):\n    attempts = []\n    best = ""\n\n    try:\n        from PIL import Image, ImageOps, ImageEnhance, ImageFilter\n        import pytesseract\n    except Exception:\n        return attempts, best\n\n    img = Image.open(crop_path)\n    w, h = img.size\n\n    # For number_crop, the full image should already be TG text.\n    # For bottom_id_crop, use right-side windows.\n    boxes = [\n        ("full", (0, 0, w, h)),\n        ("right_80", (int(w * 0.20), 0, w, h)),\n        ("right_65", (int(w * 0.35), 0, w, h)),\n        ("right_50", (int(w * 0.50), 0, w, h)),\n        ("lower_full", (0, int(h * 0.20), w, h)),\n        ("lower_right_80", (int(w * 0.20), int(h * 0.20), w, h)),\n    ]\n\n    configs = [\n        "--psm 7",\n        "--psm 8",\n        "--psm 13",\n        "--psm 6",\n        "--psm 7 -c tessedit_char_whitelist=ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/",\n        "--psm 8 -c tessedit_char_whitelist=ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/",\n        "--psm 13 -c tessedit_char_whitelist=ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/",\n    ]\n\n    for blabel, box in boxes:\n        try:\n            focus = img.crop(box)\n        except Exception:\n            continue\n\n        if focus.size[0] < 8 or focus.size[1] < 8:\n            continue\n\n        for scale in (3, 4, 5, 6, 8):\n            sw, sh = focus.size\n            base = focus.resize((sw * scale, sh * scale))\n            gray = ImageOps.grayscale(base)\n\n            variants = [\n                (f"{blabel}_raw_{scale}x", base),\n                (f"{blabel}_gray_{scale}x", gray),\n                (f"{blabel}_contrast_{scale}x", ImageEnhance.Contrast(gray).enhance(2.2)),\n                (f"{blabel}_sharp_{scale}x", ImageEnhance.Contrast(gray).enhance(2.2).filter(ImageFilter.SHARPEN)),\n                (f"{blabel}_threshold_150_{scale}x", gray.point(lambda p: 255 if p > 150 else 0)),\n                (f"{blabel}_threshold_180_{scale}x", gray.point(lambda p: 255 if p > 180 else 0)),\n            ]\n\n            for vname, im in variants:\n                for cfg in configs:\n                    try:\n                        text = pytesseract.image_to_string(im, config=cfg).strip()\n                    except Exception:\n                        text = ""\n                    repaired = _tg_v21_repair_number(text)\n                    attempts.append({\n                        "variant": vname,\n                        "config": cfg,\n                        "text": text,\n                        "repair": repaired,\n                    })\n                    if repaired:\n                        return attempts, repaired\n\n    return attempts, best\n\ndef scan_image(image_path, config, output_dir):\n    result = _previous_scan_image_before_tg_focus_v21(image_path, config, output_dir)\n\n    try:\n        if ((result.get("match") or {}).get("status") or "") == "Auto Match":\n            return result\n\n        from pathlib import Path\n        root = Path(__file__).resolve().parent\n        sqlite_path = (config or {}).get("sqlite_path", "database/putnam_pokemon_cloud_ready.sqlite")\n        rows = _tg_v21_load_rows(root / sqlite_path)\n\n        # 1) Improve name from all OCR attempts.\n        best_name, best_name_score, best_ocr_name = _tg_v21_best_name_from_attempts(result, rows)\n        result.setdefault("ocr", {})\n        result.setdefault("debug", {})\n        result["debug"]["tg_v21_best_name"] = {\n            "db_name": best_name,\n            "score": round(best_name_score, 3),\n            "ocr_source": best_ocr_name,\n        }\n\n        if best_name and best_name_score >= 0.82:\n            result["ocr"]["name_database_best"] = best_name\n            # Only replace weak/noisy name when best is clearly better.\n            current = result["ocr"].get("name", "")\n            if not current or best_name_score >= 0.88 or len(str(current)) <= 4:\n                result["ocr"]["name"] = best_name\n\n        # 2) Try TG number OCR from existing number_crop first, then bottom_id_crop.\n        debug = result.get("debug") or {}\n        urls = []\n        if debug.get("number_crop_url"):\n            urls.append(("number_crop", debug.get("number_crop_url")))\n        if debug.get("bottom_id_crop_url"):\n            urls.append(("bottom_id_crop", debug.get("bottom_id_crop_url")))\n\n        all_attempts = []\n        tg_number = ""\n        for label, url in urls:\n            p = root / url.lstrip("/").replace("/", "\\\\")\n            if not p.exists():\n                continue\n            attempts, found = _tg_v21_ocr_number_from_crop(p)\n            for a in attempts:\n                a["source_crop"] = label\n            all_attempts.extend(attempts)\n            if found:\n                tg_number = found\n                break\n\n        result.setdefault("ocr_attempts", {})\n        result["ocr_attempts"]["tg_focus_v21"] = all_attempts\n\n        if tg_number:\n            result["ocr"]["tg_focus_v21"] = tg_number\n            result["ocr"]["number"] = tg_number\n            result["ocr"]["bottom_id"] = tg_number\n\n        # 3) If we have TG number, try DB-assisted matching using improved name.\n        if tg_number and "_db_assist_match_from_number_v1" in globals():\n            match_name = result["ocr"].get("name_database_best") or result["ocr"].get("name", "")\n            match, candidates = _db_assist_match_from_number_v1(rows, match_name, tg_number)\n            if candidates:\n                result["candidates"] = candidates\n            if match:\n                result["match"] = match\n                result["status"] = match.get("status", "Auto Match")\n                result["ocr"]["database_corrected_name"] = match.get("card_name", "")\n\n        return result\n\n    except Exception as exc:\n        result.setdefault("debug", {})\n        result["debug"]["tg_focus_v21_error"] = str(exc)\n        return result\n'

TARGET.write_text(s + "\n" + append, encoding="utf-8")

print("SUCCESS: TG OCR Focus v2.1 patch installed.")
print(f"Backup created: {BACKUP}")
print("Changed file: scanner_core_region_ocr.py")
print("")
print("What changed:")
print("- Chooses better name by comparing all name OCR attempts against database card names")
print("- Adds TG-number-only OCR from number_crop first, then bottom_id_crop")
print("- Repairs TG02/TG30 and similar forms")
print("- Attempts DB-assisted match using improved name + TG number")
print("")
print("Files intentionally NOT changed:")
print("- known_good/template_region_warp_matcher_v0_7.py")
print("- known_good/IMG_7505.json")
print("- known_good/IMG_7507.json")
print("- scanner_studio.html")
print("- scanner_server.py")
print("")
